```nginx
http {
    # Inbound client headers (prevents 400 Request Header Or Cookie Too Large)
    large_client_header_buffers 4 16k;

    # Upstream response headers + body (4KB OS page aligned)
    proxy_buffer_size       16k;
    proxy_buffers           8 16k;
    proxy_busy_buffers_size 32k;
}
```
